import { Component } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { Etnia } from '../../../models/etnia.model';
import { EtniaService } from '../../../controllers/etnia.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';

const FORM_DEF:Form=[
  {
    key:'nombre',
    label:'Etnia',
    type:'text',
    style:{
      div:'col-12 p-3'
    }
  }
]

@Component({
    selector: 'app-form-etnia',
    imports: [
        GenericFormComponent,
    ],
    templateUrl: './form-etnia.component.html',
    styleUrl: './form-etnia.component.css'
})
export class FormEtniaComponent {
  etnia?:Etnia
  form= FORM_DEF
  constructor(
    public etniaController:EtniaService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id = this.utils.intOrNull(params.get('discapacidad_id'))
      if(id){
        this.etnia=await this.etniaController.find(id)
      }
    })
  }
}
